INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000021d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urban development at B2","Use Stadtentwicklung vocabulary","Talk about smart cities and urban planning"],"explanation":{"intro":"Urban development vocabulary covers city planning, smart cities, and urban challenges at B2.","culturalNote":"German Stadtentwicklung: Bundesinstitut für Bau-, Stadt- und Raumforschung (BBSR) coordinates. Key concepts: Gentrification (Gentrifizierung), Leerstand (vacancy), Smart City (Berlin, Hamburg, Munich projects), Schwammstadt (sponge city — water management), soziale Wohnraumförderung (social housing promotion). Key challenge: Wachstumsregionen vs. schrumpfende Regionen (growing vs. shrinking regions). EU-Förderprogramme for urban regeneration. Leipzig Charta (2007, 2020) on integrated urban development."},"examples":[{"german":"Nachhaltige Stadtentwicklung muss ökologische, soziale und wirtschaftliche Dimensionen integrieren, statt sie als getrennte Politikbereiche zu behandeln.","english":"Sustainable urban development must integrate ecological, social, and economic dimensions, rather than treating them as separate policy areas."},{"german":"Gentrifizierung beschreibt den Prozess, durch den einkommensschwache Bevölkerungsgruppen aus aufgewerteten Stadtvierteln verdrängt werden.","english":"Gentrification describes the process by which low-income population groups are displaced from upgraded urban districts."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss urban development, gentrification, and smart cities at B2."}}',
'{"items":[{"word":"integrieren","translation":"to integrate","pronunciation":"in-teh-GREER-en","example":"Dimensionen integrieren."},{"word":"getrennt","translation":"separate","pronunciation":"geh-TRENT","example":"Getrennte Politikbereiche."},{"word":"die Aufwertung","translation":"upgrading/appreciation","pronunciation":"dee OWF-ver-toong","example":"Aufwertung von Stadtvierteln."},{"word":"verdrängen","translation":"to displace/push out","pronunciation":"fer-DRENG-en","example":"Aus Vierteln verdrängen."},{"word":"einkommensschwach","translation":"low-income","pronunciation":"YN-ko-mens-shvakh","example":"Einkommensschwache Gruppen."},{"word":"der Prozess","translation":"process","pronunciation":"dayr pro-TSES","example":"Ein Prozess der Verdrängung."}]}',
'{"title":"Statt ... zu ... — instead of (doing) — same subject, formal variant","pattern":"statt + zu + Infinitiv = instead of doing (same subject, parallel to anstatt zu)","explanation":"Statt zu + Infinitiv = instead of doing (same subject required; shorter/more colloquial than anstatt zu, both are correct). Statt sie als getrennte Bereiche zu behandeln = instead of treating them as separate areas. Statt can also be a preposition + noun: statt einer Reform (instead of a reform). As a conjunction with clause and different subject: statt dass + V-final. Note: both statt and anstatt are equally correct in written German; statt is slightly more common in everyday speech.","examples":[{"sentence":"Statt zu klagen, sollten wir handeln.","translation":"Instead of complaining, we should act."},{"sentence":"Er aß das Gemüse, statt es auf dem Teller liegenzulassen.","translation":"He ate the vegetables instead of leaving them on his plate."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdrängen'' means?","options":["to displace/push out","to repress","to replace","to evict"],"correctAnswer":"to displace/push out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gentrification describes the process by which low-income population groups are displaced from upgraded urban districts.","options":["Gentrifizierung beschreibt den Prozess, durch den einkommensschwache Bevölkerungsgruppen aus aufgewerteten Stadtvierteln verdrängt werden.","Gentrifizierung bedeutet, dass Reiche in arme Viertel ziehen.","Durch Gentrifizierung steigen die Mieten und arme Menschen müssen wegziehen.","Stadtteile werden aufgewertet, aber Einkommensschwache werden verdrängt."],"correctAnswer":"Gentrifizierung beschreibt den Prozess, durch den einkommensschwache Bevölkerungsgruppen aus aufgewerteten Stadtvierteln verdrängt werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Statt zu klagen, sollten wir ___.","options":["handeln","reagieren","handeln","etwas tun"],"correctAnswer":"handeln"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Sustainable urban development must integrate ecological social and economic dimensions","wordBankItems":["Nachhaltige","Stadtentwicklung","muss","ökologische",",","soziale","und","wirtschaftliche","Dimensionen","integrieren","."],"correctAnswer":"Nachhaltige Stadtentwicklung muss ökologische , soziale und wirtschaftliche Dimensionen integrieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Einkommensschwach'' means?","options":["low-income","poor","underprivileged","economically weak"],"correctAnswer":"low-income"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000021e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss housing policy at B2","Use Wohnungspolitik vocabulary","Talk about housing affordability and rent control"],"explanation":{"intro":"Housing policy vocabulary covers rent regulation, social housing, and housing shortages at B2.","culturalNote":"Germany has one of the lowest homeownership rates in the EU (~50%): most Germans rent. Key issues: Mietpreisbremse (rent brake — introduced 2015, extended), Mietendeckel (Berlin rent cap 2020 — declared unconstitutional 2021), sozialer Wohnungsbau (social housing — shrinking stock), Wohnungsnot (housing shortage — especially in cities: Berlin, Munich, Hamburg, Frankfurt). Mietervereine (tenants'' associations) powerful. Deutsche Wohnen & Co. enteignen initiative in Berlin."},"examples":[{"german":"Die Wohnungsnot in deutschen Großstädten ist das Ergebnis jahrzehntelanger Vernachlässigung des sozialen Wohnungsbaus und staatlicher Deregulierung des Wohnungsmarkts.","english":"The housing shortage in German cities is the result of decades of neglect of social housing construction and state deregulation of the housing market."},{"german":"Mietpreisregulierungen sind ein Instrument zur Bekämpfung von Wohnungsknappheit, werden jedoch von Ökonomen kontrovers diskutiert, da sie Anreize für Neubauten verringern können.","english":"Rent price regulations are an instrument for combating housing shortages, but are controversially discussed by economists since they can reduce incentives for new construction."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss housing policy, rent regulation, and housing shortages at B2."}}',
'{"items":[{"word":"die Vernachlässigung","translation":"neglect","pronunciation":"dee fer-NAKH-läs-i-goong","example":"Vernachlässigung des Wohnungsbaus."},{"word":"die Deregulierung","translation":"deregulation","pronunciation":"dee deh-reh-goo-LEER-oong","example":"Staatliche Deregulierung."},{"word":"die Knappheit","translation":"shortage/scarcity","pronunciation":"dee KNAP-hyt","example":"Wohnungsknappheit."},{"word":"der Anreiz","translation":"incentive","pronunciation":"dayr AN-ryts","example":"Anreize verringern."},{"word":"der Neubau","translation":"new construction","pronunciation":"dayr NOY-bow","example":"Anreize für Neubauten."},{"word":"kontrovers","translation":"controversially","pronunciation":"kon-tro-VERS","example":"Kontrovers diskutiert."}]}',
'{"title":"Da — since/because (causal subordinating conjunction)","pattern":"da + V-final = since, because, as (causal — especially when the reason is already known or contextually obvious)","explanation":"Da = since, because (causal subordinating conjunction — V-final). Ökonomen diskutieren kontrovers, da Regulierungen Anreize verringern können = Economists discuss controversially, since regulations can reduce incentives. Da is preferred over weil when the reason is already known to both speaker and listener, or is contextually established (shared knowledge). Weil is more natural for new information. Both are correct; da feels more formal/written. Da at the start of the sentence: Da er krank war, blieb er zuhause.","examples":[{"sentence":"Da die Nachfrage gestiegen ist, haben wir die Preise angepasst.","translation":"Since demand has increased, we have adjusted the prices."},{"sentence":"Wir müssen schnell handeln, da die Zeit knapp wird.","translation":"We must act quickly, since time is running short."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Knappheit'' means?","options":["shortage/scarcity","lack","deficit","insufficiency"],"correctAnswer":"shortage/scarcity"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The housing shortage in German cities is the result of decades of neglect of social housing construction and state deregulation of the housing market.","options":["Die Wohnungsnot in deutschen Großstädten ist das Ergebnis jahrzehntelanger Vernachlässigung des sozialen Wohnungsbaus und staatlicher Deregulierung des Wohnungsmarkts.","Wohnungsmangel entsteht durch fehlenden Neubau und Deregulierung.","Der soziale Wohnungsbau wurde jahrzehntelang vernachlässigt.","Deregulierung und fehlender Sozialbau haben zur Wohnungsnot geführt."],"correctAnswer":"Die Wohnungsnot in deutschen Großstädten ist das Ergebnis jahrzehntelanger Vernachlässigung des sozialen Wohnungsbaus und staatlicher Deregulierung des Wohnungsmarkts."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Da die Nachfrage gestiegen ist, haben wir die Preise ___.","options":["angepasst","erhöht","verändert","korrigiert"],"correctAnswer":"angepasst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We must act quickly since time is running short","wordBankItems":["Wir","müssen","schnell","handeln",",","da","die","Zeit","knapp","wird","."],"correctAnswer":"Wir müssen schnell handeln , da die Zeit knapp wird ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Anreiz'' means?","options":["incentive","motivation","stimulus","inducement"],"correctAnswer":"incentive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000021f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss future mobility at B2","Use Mobilität vocabulary","Talk about autonomous vehicles and transport policy"],"explanation":{"intro":"Future mobility vocabulary covers autonomous driving, e-mobility, and transport policy at B2.","culturalNote":"Germany is the home of the automobile (Benz, Daimler — first cars 1885). Key transitions: Elektromobilität (e-mobility — 2030 target: 15 million EVs), autonomes Fahren (autonomous driving — Levels 1-5, Germany first country to allow Level 4 in 2021), Mobilitätswende (mobility transition), Verkehrswende (transport transition). Key challenges: Ladeinfrastruktur (charging infrastructure), Reichweitenangst (range anxiety), ÖPNV-Ausbau (public transport expansion)."},"examples":[{"german":"Autonomes Fahren verspricht nicht nur mehr Verkehrssicherheit, sondern auch eine effizientere Nutzung der Straßeninfrastruktur durch vernetztes Fahren.","english":"Autonomous driving promises not only greater road safety, but also more efficient use of road infrastructure through connected driving."},{"german":"Die Mobilitätswende erfordert ein grundlegendes Umdenken: weg vom Besitz privater Kraftfahrzeuge hin zu integrierten, multimodalen Mobilitätsangeboten.","english":"The mobility transition requires a fundamental rethink: away from ownership of private vehicles towards integrated, multimodal mobility offerings."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss future mobility, autonomous driving, and the mobility transition at B2."}}',
'{"items":[{"word":"vernetzt","translation":"networked/connected","pronunciation":"fer-NETST","example":"Vernetztes Fahren."},{"word":"das Umdenken","translation":"rethink/change of mindset","pronunciation":"dahs OOM-den-ken","example":"Grundlegendes Umdenken."},{"word":"multimodal","translation":"multimodal","pronunciation":"mul-ti-mo-DAHL","example":"Multimodale Angebote."},{"word":"integriert","translation":"integrated","pronunciation":"in-teh-GREERT","example":"Integrierte Mobilitätsangebote."},{"word":"weg von ... hin zu","translation":"away from ... towards","pronunciation":"vek fon ... hin tsoo","example":"Weg von Besitz hin zu Angeboten."},{"word":"das Kraftfahrzeug","translation":"motor vehicle","pronunciation":"dahs KRAFT-fahr-tsoyg","example":"Private Kraftfahrzeuge."}]}',
'{"title":"Weg von ... hin zu — away from ... towards (directional transition)","pattern":"weg von X hin zu Y = away from X towards Y (signals a directional transition in policy, society, or thinking)","explanation":"Weg von X hin zu Y = away from X, towards Y (describes a transition from an old state to a new one — common in policy and societal discourse). Die Mobilitätswende führt weg vom Auto hin zum ÖPNV = The mobility transition leads away from the car towards public transport. This pattern signals intent or process of change. Weg von (away from) + dative; hin zu (towards) + dative. Compare: von X zu Y (from X to Y — more neutral, just movement), von X nach Y (from X to Y — usually places).","examples":[{"sentence":"Der Trend geht weg von der Massenware hin zu nachhaltigen Produkten.","translation":"The trend moves away from mass-produced goods towards sustainable products."},{"sentence":"Die Gesellschaft entwickelt sich weg von starren Rollenmodellen hin zu mehr Flexibilität.","translation":"Society is developing away from rigid role models towards greater flexibility."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vernetzt'' means?","options":["networked/connected","linked","interconnected","online"],"correctAnswer":"networked/connected"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The mobility transition requires a fundamental rethink: away from ownership of private vehicles towards integrated, multimodal mobility offerings.","options":["Die Mobilitätswende erfordert ein grundlegendes Umdenken: weg vom Besitz privater Kraftfahrzeuge hin zu integrierten, multimodalen Mobilitätsangeboten.","Die Mobilitätswende bedeutet weniger Autos und mehr ÖPNV.","Mobilität der Zukunft ist multimodal und vernetzt.","Vom privaten Auto zum öffentlichen Verkehr ist die Zukunft."],"correctAnswer":"Die Mobilitätswende erfordert ein grundlegendes Umdenken: weg vom Besitz privater Kraftfahrzeuge hin zu integrierten, multimodalen Mobilitätsangeboten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Trend geht weg von der Massenware hin zu nachhaltigen ___.","options":["Produkten","Waren","Gütern","Artikeln"],"correctAnswer":"Produkten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Society is developing away from rigid role models towards greater flexibility","wordBankItems":["Die","Gesellschaft","entwickelt","sich","weg","von","starren","Rollenmodellen","hin","zu","mehr","Flexibilität","."],"correctAnswer":"Die Gesellschaft entwickelt sich weg von starren Rollenmodellen hin zu mehr Flexibilität ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Umdenken'' means?","options":["rethink/change of mindset","change of mind","reconsidering","paradigm shift"],"correctAnswer":"rethink/change of mindset"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000220',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss public transport at B2","Use ÖPNV vocabulary","Talk about transport infrastructure"],"explanation":{"intro":"Public transport vocabulary covers urban transit systems, rail policy, and transport planning at B2.","culturalNote":"Germany''s ÖPNV (Öffentlicher Personennahverkehr): U-Bahn (metro), S-Bahn (city rail), Straßenbahn (tram), Bus. Deutsche Bahn (DB) — national rail, partly privatised 1994. Key issues: Verspätungen (delays — DB reliability criticised), Schienennetz-Investitionen (rail network investment), Deutschlandticket (€49/month nationwide public transport ticket, introduced 2023 — major policy success, 11+ million subscribers). Verkehrsverbünde (transport associations — coordinate ticketing). ÖPNV in rural areas often inadequate."},"examples":[{"german":"Ein leistungsfähiger öffentlicher Nahverkehr ist eine zentrale Voraussetzung für die Verkehrswende, da er Alternativen zum Individualverkehr bietet und zur Reduzierung von CO₂-Emissionen beiträgt.","english":"Efficient public transport is a central precondition for the mobility transition, as it offers alternatives to private transport and contributes to the reduction of CO₂ emissions."},{"german":"Das Deutschlandticket hat gezeigt, dass günstige, einfache Preismodelle die Nachfrage nach öffentlichen Verkehrsmitteln erheblich steigern können.","english":"The Germany ticket has shown that affordable, simple pricing models can considerably increase demand for public transport."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss public transport, rail policy, and the Deutschlandticket at B2."}}',
'{"items":[{"word":"leistungsfähig","translation":"efficient/high-performance","pronunciation":"LYS-toonks-fä-ikh","example":"Leistungsfähiger ÖPNV."},{"word":"die Voraussetzung","translation":"precondition","pronunciation":"dee for-OWS-zetsoong","example":"Zentrale Voraussetzung."},{"word":"der Individualverkehr","translation":"private transport","pronunciation":"dayr in-di-vi-doo-AHL-fer-kayr","example":"Alternative zum Individualverkehr."},{"word":"beitragen zu","translation":"to contribute to","pronunciation":"BY-trah-gen tsoo","example":"Zur Reduzierung beitragen."},{"word":"erheblich","translation":"considerably/significantly","pronunciation":"er-HEB-likh","example":"Erheblich steigern."},{"word":"das Preismodell","translation":"pricing model","pronunciation":"dahs PRYS-mo-del","example":"Einfaches Preismodell."}]}',
'{"title":"Beitragen zu — to contribute to (separable)","pattern":"etwas trägt zu etwas (Dativ) bei = something contributes to something (separable)","explanation":"Beitragen zu + dative (separable) = to contribute to. ÖPNV trägt zur Reduzierung von Emissionen bei = Public transport contributes to the reduction of emissions. Present: trägt bei. Perfect: hat beigetragen. The prefix bei- is separated: trägt...bei. Der Beitrag = contribution. Compare: helfen bei (to help with — more personal/direct assistance), fördern (to promote/support — active promotion), unterstützen (to support), dazu beitragen, dass... (to contribute to the fact that... — followed by clause).","examples":[{"sentence":"Digitalisierung trägt zur Effizienz öffentlicher Verwaltung bei.","translation":"Digitalisation contributes to the efficiency of public administration."},{"sentence":"Jeder kann dazu beitragen, den Klimawandel zu verlangsamen.","translation":"Everyone can contribute to slowing down climate change."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Leistungsfähig'' means?","options":["efficient/high-performance","capable","productive","effective"],"correctAnswer":"efficient/high-performance"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Germany ticket has shown that affordable, simple pricing models can considerably increase demand for public transport.","options":["Das Deutschlandticket hat gezeigt, dass günstige, einfache Preismodelle die Nachfrage nach öffentlichen Verkehrsmitteln erheblich steigern können.","Das Deutschlandticket macht den ÖPNV günstiger und attraktiver.","Günstige Tickets erhöhen die Nutzung öffentlicher Verkehrsmittel.","Das Deutschlandticket ist ein Erfolgsmodell für den öffentlichen Nahverkehr."],"correctAnswer":"Das Deutschlandticket hat gezeigt, dass günstige, einfache Preismodelle die Nachfrage nach öffentlichen Verkehrsmitteln erheblich steigern können."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Digitalisierung trägt zur Effizienz öffentlicher Verwaltung ___.","options":["bei","mit","zu","dazu"],"correctAnswer":"bei"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Everyone can contribute to slowing down climate change","wordBankItems":["Jeder","kann","dazu","beitragen",",","den","Klimawandel","zu","verlangsamen","."],"correctAnswer":"Jeder kann dazu beitragen , den Klimawandel zu verlangsamen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erheblich'' means?","options":["considerably/significantly","substantially","noticeably","markedly"],"correctAnswer":"considerably/significantly"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000221',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital infrastructure at B2","Use digitale Infrastruktur vocabulary","Talk about broadband and connectivity"],"explanation":{"intro":"Digital infrastructure vocabulary covers broadband expansion, 5G, and digital connectivity at B2.","culturalNote":"Germany lags in digital infrastructure: Breitbandausbau (broadband expansion) slow compared to EU peers. Glasfaser (fibre optic) rollout behind schedule. 5G-Ausbau ongoing. Key issues: Funklöcher (mobile dead zones — especially rural), Bundesnetzagentur (Federal Network Agency — regulates telecoms), digitale Kluft (digital divide — between urban and rural, older and younger). Bundesdigitalministerium (Federal Digital Ministry) since 2021. Ziel: Gigabitnetz bis 2030."},"examples":[{"german":"Die digitale Infrastruktur eines Landes ist eine Grundvoraussetzung für wirtschaftliche Wettbewerbsfähigkeit und gesellschaftliche Teilhabe im 21. Jahrhundert.","english":"The digital infrastructure of a country is a fundamental precondition for economic competitiveness and social participation in the 21st century."},{"german":"Die digitale Kluft zwischen gut angebundenen urbanen Zentren und schlecht versorgten ländlichen Regionen verschärft bestehende Ungleichheiten.","english":"The digital divide between well-connected urban centres and poorly served rural regions intensifies existing inequalities."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital infrastructure, broadband, and the digital divide at B2."}}',
'{"items":[{"word":"die Grundvoraussetzung","translation":"fundamental precondition","pronunciation":"dee GROOND-for-owss-zetsoong","example":"Grundvoraussetzung für Teilhabe."},{"word":"die Wettbewerbsfähigkeit","translation":"competitiveness","pronunciation":"dee VET-beh-verps-fä-ikh-kyt","example":"Wirtschaftliche Wettbewerbsfähigkeit."},{"word":"angebunden","translation":"connected/linked","pronunciation":"AN-geh-boon-den","example":"Gut angebunden."},{"word":"verschärfen","translation":"to intensify/worsen","pronunciation":"fer-SHER-fen","example":"Ungleichheiten verschärfen."},{"word":"versorgen","translation":"to supply/serve","pronunciation":"fer-ZOR-gen","example":"Schlecht versorgte Regionen."},{"word":"die Kluft","translation":"divide/gap","pronunciation":"dee klooft","example":"Digitale Kluft."}]}',
'{"title":"Verschärfen — to intensify, worsen, exacerbate (transitive)","pattern":"etwas verschärft etwas = something intensifies/worsens something; sich verschärfen = to intensify (intransitive)","explanation":"Verschärfen = to intensify, worsen, exacerbate (transitive — one thing makes another worse). Die digitale Kluft verschärft bestehende Ungleichheiten = The digital divide exacerbates existing inequalities. Reflexive: die Situation verschärft sich = the situation is worsening. Perfect: hat verschärft / hat sich verschärft. Compare: verstärken (to reinforce/amplify — can be positive or neutral), verschlechtern (to worsen — more general deterioration), zuspitzen (to come to a head — for crises).","examples":[{"sentence":"Die Pandemie hat soziale Ungleichheiten weltweit verschärft.","translation":"The pandemic has exacerbated social inequalities worldwide."},{"sentence":"Der Konflikt verschärfte sich nach den gescheiterten Verhandlungen.","translation":"The conflict intensified after the failed negotiations."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Angebunden'' means?","options":["connected/linked","attached","tied","joined"],"correctAnswer":"connected/linked"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The digital divide between well-connected urban centres and poorly served rural regions intensifies existing inequalities.","options":["Die digitale Kluft zwischen gut angebundenen urbanen Zentren und schlecht versorgten ländlichen Regionen verschärft bestehende Ungleichheiten.","In Städten ist die digitale Infrastruktur besser als auf dem Land.","Ländliche Regionen haben schlechteren Internetzugang als Städte.","Die digitale Ungleichheit zwischen Stadt und Land wächst."],"correctAnswer":"Die digitale Kluft zwischen gut angebundenen urbanen Zentren und schlecht versorgten ländlichen Regionen verschärft bestehende Ungleichheiten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Pandemie hat soziale Ungleichheiten weltweit ___.","options":["verschärft","verstärkt","vertieft","vergrößert"],"correctAnswer":"verschärft"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The conflict intensified after the failed negotiations","wordBankItems":["Der","Konflikt","verschärfte","sich","nach","den","gescheiterten","Verhandlungen","."],"correctAnswer":"Der Konflikt verschärfte sich nach den gescheiterten Verhandlungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Wettbewerbsfähigkeit'' means?","options":["competitiveness","competitive capacity","competition ability","market position"],"correctAnswer":"competitiveness"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000222',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the energy transition at B2","Use Energiewende vocabulary","Talk about renewables and energy policy"],"explanation":{"intro":"Energiewende vocabulary covers Germany''s energy transition, renewables, and grid challenges at B2.","culturalNote":"Energiewende (energy transition) = Germany''s shift from nuclear/fossil fuels to renewables. Key milestones: nuclear phase-out completed April 2023 (last 3 plants), coal phase-out target 2038 (moved up to 2030 possible). Key metrics: ~60% renewable electricity (2023). Key challenges: Netzstabilität (grid stability), Speichertechnologie (storage technology), hohe Strompreise (high electricity prices — among highest in Europe), Akzeptanz (public acceptance — wind turbine NIMBYism). Key actors: Bundesnetzagentur, Netz4 Deutschland."},"examples":[{"german":"Die Energiewende ist ein ambitioniertes Transformationsprojekt, das technische Innovation, politischen Willen und gesellschaftliche Akzeptanz in gleichem Maße erfordert.","english":"The energy transition is an ambitious transformation project that requires technical innovation, political will, and social acceptance in equal measure."},{"german":"Der Ausbau erneuerbarer Energien schreitet voran, stößt jedoch auf Hindernisse wie langwierige Genehmigungsverfahren und unzureichende Netzkapazitäten.","english":"The expansion of renewable energies is progressing, but encounters obstacles such as lengthy approval procedures and inadequate grid capacities."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the energy transition, renewables, and energy policy at B2."}}',
'{"items":[{"word":"ambitioniert","translation":"ambitious","pronunciation":"am-bi-tsyo-NEERT","example":"Ambitioniertes Projekt."},{"word":"in gleichem Maße","translation":"in equal measure","pronunciation":"in GLY-khem MAH-seh","example":"In gleichem Maße erfordern."},{"word":"stoßen auf","translation":"to encounter/meet with","pronunciation":"SHTO-sen owf","example":"Auf Hindernisse stoßen."},{"word":"das Hindernis","translation":"obstacle","pronunciation":"dahs HIN-der-nis","example":"Hindernisse überwinden."},{"word":"das Genehmigungsverfahren","translation":"approval procedure","pronunciation":"dahs geh-NAY-mi-goonks-fer-fah-ren","example":"Langwieriges Genehmigungsverfahren."},{"word":"unzureichend","translation":"inadequate/insufficient","pronunciation":"OON-tsoo-ry-khend","example":"Unzureichende Kapazitäten."}]}',
'{"title":"Stoßen auf — to encounter, come up against (separable)","pattern":"auf etwas stoßen = to encounter, come across, meet with (separable — used for obstacles or discoveries)","explanation":"Stoßen auf + accusative (separable) = to encounter, run into, come up against (for obstacles, problems, resistance) OR to come across, discover (for findings, ideas). Der Ausbau stößt auf Hindernisse = The expansion encounters obstacles. Der Forscher stieß auf interessante Daten = The researcher came across interesting data. Present: stößt auf. Perfect: ist gestoßen auf (movement/encounter) or hat gestoßen auf. Compare: treffen auf (to meet/encounter — people or situations), begegnen (dative — to encounter — more neutral), auf Widerstand treffen (to meet with resistance).","examples":[{"sentence":"Die Idee stieß auf wenig Gegenliebe.","translation":"The idea met with little enthusiasm."},{"sentence":"Bei der Ausgrabung stießen sie auf antike Münzen.","translation":"During the excavation they came across ancient coins."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unzureichend'' means?","options":["inadequate/insufficient","deficient","lacking","substandard"],"correctAnswer":"inadequate/insufficient"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The expansion of renewable energies is progressing, but encounters obstacles such as lengthy approval procedures and inadequate grid capacities.","options":["Der Ausbau erneuerbarer Energien schreitet voran, stößt jedoch auf Hindernisse wie langwierige Genehmigungsverfahren und unzureichende Netzkapazitäten.","Der Ausbau erneuerbarer Energien geht langsam voran.","Bürokratische Hürden verlangsamen den Ausbau der Erneuerbaren.","Netzkapazitäten und Genehmigungen sind Probleme für die Energiewende."],"correctAnswer":"Der Ausbau erneuerbarer Energien schreitet voran, stößt jedoch auf Hindernisse wie langwierige Genehmigungsverfahren und unzureichende Netzkapazitäten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Idee stieß auf wenig ___.","options":["Gegenliebe","Begeisterung","Akzeptanz","Zustimmung"],"correctAnswer":"Gegenliebe"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: During the excavation they came across ancient coins","wordBankItems":["Bei","der","Ausgrabung","stießen","sie","auf","antike","Münzen","."],"correctAnswer":"Bei der Ausgrabung stießen sie auf antike Münzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ambitioniert'' means?","options":["ambitious","aspiring","determined","goal-oriented"],"correctAnswer":"ambitious"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000223',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss climate policy at B2","Use Klimaschutzpolitik vocabulary","Talk about carbon pricing and climate targets"],"explanation":{"intro":"Climate policy vocabulary covers emissions trading, carbon pricing, and international climate agreements at B2.","culturalNote":"Germany''s Klimaschutzgesetz (Climate Protection Act 2019, amended 2021): sector-specific emissions targets. Key milestones: Klimaneutralität 2045, intermediate targets by sector. Key instruments: EU-Emissionshandel (ETS — EU Emissions Trading System), nationaler CO₂-Preis (national carbon price — €25/t in 2021, rising), Klimaschutzsofortprogramm. Key actors: Bundesklimaschutzminister (Robert Habeck FDP/Greens era). Paris Agreement 1.5°C target, Germany NDCs. Klimaklagen (climate lawsuits — Neubauer et al. vs. Germany, BVerfG 2021 — landmark ruling)."},"examples":[{"german":"CO₂-Bepreisung gilt als das effektivste marktwirtschaftliche Instrument zur Internalisierung externer Klimakosten, da sie Anreize für Emissionsreduktionen in allen Sektoren schafft.","english":"CO₂ pricing is regarded as the most effective market-based instrument for internalising external climate costs, as it creates incentives for emissions reductions across all sectors."},{"german":"Die Verpflichtung zur Klimaneutralität bis 2045 setzt Deutschland unter erheblichen Transformationsdruck, der alle Sektoren der Wirtschaft betrifft.","english":"The commitment to climate neutrality by 2045 places Germany under considerable transformation pressure, which affects all sectors of the economy."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss climate policy, carbon pricing, and climate targets at B2."}}',
'{"items":[{"word":"die Internalisierung","translation":"internalisation","pronunciation":"dee in-ter-nah-li-ZEER-oong","example":"Internalisierung externer Kosten."},{"word":"extern","translation":"external","pronunciation":"eks-TERN","example":"Externe Klimakosten."},{"word":"der Transformationsdruck","translation":"transformation pressure","pronunciation":"dayr trans-for-mah-TSYOHNS-drook","example":"Erheblicher Transformationsdruck."},{"word":"die Verpflichtung","translation":"commitment/obligation","pronunciation":"dee fer-PFLIKHT-oong","example":"Verpflichtung zur Klimaneutralität."},{"word":"betreffen","translation":"to affect","pronunciation":"beh-TREF-en","example":"Alle Sektoren betreffen."},{"word":"die Bepreisung","translation":"pricing","pronunciation":"dee beh-PRY-zoong","example":"CO₂-Bepreisung."}]}',
'{"title":"Unter Druck setzen / unter Druck stehen — to put under pressure / to be under pressure","pattern":"jemanden unter Druck setzen = to put someone under pressure; unter Druck stehen = to be under pressure","explanation":"Unter Druck setzen = to put under pressure (transitive). Unter Druck stehen = to be under pressure (intransitive — ongoing state). Die Verpflichtung setzt Deutschland unter Transformationsdruck = The commitment places Germany under transformation pressure. Unter Druck geraten = to come under pressure (become subject to). Common in political, business, and personal contexts. Compare: belasten (to burden/strain — physical/psychological), zwingen (to force — stronger compulsion), drängen (to press/urge — interpersonal).","examples":[{"sentence":"Die öffentliche Debatte hat das Unternehmen unter Druck gesetzt.","translation":"The public debate has put the company under pressure."},{"sentence":"Unter diesem Druck stehend, fiel die Entscheidung schwer.","translation":"Standing under this pressure, the decision was difficult."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Internalisierung'' means?","options":["internalisation","incorporation","internalizing","inclusion"],"correctAnswer":"internalisation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"CO₂ pricing is regarded as the most effective market-based instrument for internalising external climate costs, as it creates incentives for emissions reductions across all sectors.","options":["CO₂-Bepreisung gilt als das effektivste marktwirtschaftliche Instrument zur Internalisierung externer Klimakosten, da sie Anreize für Emissionsreduktionen in allen Sektoren schafft.","Ein CO₂-Preis schafft Anreize zur Emissionsreduzierung.","Marktwirtschaftliche Instrumente sind effektiver als Verbote.","CO₂-Bepreisung internalisiert Klimakosten und fördert Reduktionen."],"correctAnswer":"CO₂-Bepreisung gilt als das effektivste marktwirtschaftliche Instrument zur Internalisierung externer Klimakosten, da sie Anreize für Emissionsreduktionen in allen Sektoren schafft."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die öffentliche Debatte hat das Unternehmen unter Druck ___.","options":["gesetzt","gebracht","gestellt","genommen"],"correctAnswer":"gesetzt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The commitment places Germany under considerable transformation pressure","wordBankItems":["Die","Verpflichtung","setzt","Deutschland","unter","erheblichen","Transformationsdruck","."],"correctAnswer":"Die Verpflichtung setzt Deutschland unter erheblichen Transformationsdruck ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Betreffen'' means?","options":["to affect","to concern","to relate to","to impact"],"correctAnswer":"to affect"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000224',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss resource policy at B2","Use Ressourcenpolitik vocabulary","Talk about critical raw materials and circular economy"],"explanation":{"intro":"Resource policy vocabulary covers critical raw materials, circular economy, and resource scarcity at B2.","culturalNote":"Germany imports almost all strategic raw materials: Lithium (batteries), Kobalt, seltene Erden (rare earth elements — from China ~60%), Kupfer. Key policy: Nationale Rohstoffstrategie (National Raw Materials Strategy). Key concepts: Kreislaufwirtschaft (circular economy — EU taxonomy), Urban Mining (recycling metals from waste), Lieferkettengesetz (Supply Chain Act 2023 — corporate due diligence). EU-Rohstoffgesetz (Critical Raw Materials Act 2024). Critical for energy transition and chip manufacturing."},"examples":[{"german":"Die Abhängigkeit von Importen kritischer Rohstoffe stellt eine strategische Verwundbarkeit dar, die durch Diversifizierung der Bezugsquellen und Investitionen in Recyclingtechnologie reduziert werden kann.","english":"Dependence on imports of critical raw materials represents a strategic vulnerability that can be reduced through diversification of sources and investment in recycling technology."},{"german":"Eine konsequente Kreislaufwirtschaft würde den Bedarf an primären Rohstoffen erheblich senken und gleichzeitig die ökologische Belastung der Extraktion verringern.","english":"A consistent circular economy would considerably reduce the need for primary raw materials and at the same time decrease the ecological burden of extraction."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss resource policy, critical raw materials, and circular economy at B2."}}',
'{"items":[{"word":"die Verwundbarkeit","translation":"vulnerability","pronunciation":"dee fer-VOOND-bahr-kyt","example":"Strategische Verwundbarkeit."},{"word":"die Bezugsquelle","translation":"source of supply","pronunciation":"dee beh-TSOOKS-kwel-eh","example":"Diversifizierung der Bezugsquellen."},{"word":"konsequent","translation":"consistent/consequent","pronunciation":"kon-zeh-KVENT","example":"Konsequente Kreislaufwirtschaft."},{"word":"primär","translation":"primary","pronunciation":"pri-MÄR","example":"Primäre Rohstoffe."},{"word":"die Extraktion","translation":"extraction","pronunciation":"dee eks-trak-TSYOHN","example":"Extraktion von Rohstoffen."},{"word":"senken","translation":"to reduce/lower","pronunciation":"ZENG-ken","example":"Den Bedarf senken."}]}',
'{"title":"Darstellen — to represent, constitute (key academic verb)","pattern":"etwas stellt etwas dar = something represents/constitutes something (separable — academic/formal)","explanation":"Darstellen (separable) = to represent, constitute, present (academic). Die Abhängigkeit stellt eine Verwundbarkeit dar = Dependence constitutes a vulnerability (= is a vulnerability — more formal than ist). Present: stellt dar. Perfect: hat dargestellt. Also: etwas darstellen = to depict/show (in art, diagrams). Commonly used in academic writing instead of ''sein'' to elevate register. Compare: bilden (to form/constitute — similar formal register), ausmachen (to constitute/make up — especially proportions), verkörpern (to embody).","examples":[{"sentence":"Dieser Befund stellt eine wichtige Erkenntnis für die weitere Forschung dar.","translation":"This finding constitutes an important insight for further research."},{"sentence":"Die hohe Inflation stellt ein erhebliches Risiko für die Wirtschaft dar.","translation":"The high inflation constitutes a considerable risk for the economy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Konsequent'' means?","options":["consistent/consequent","logical","rigorous","systematic"],"correctAnswer":"consistent/consequent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Dependence on imports of critical raw materials represents a strategic vulnerability that can be reduced through diversification of sources and investment in recycling technology.","options":["Die Abhängigkeit von Importen kritischer Rohstoffe stellt eine strategische Verwundbarkeit dar, die durch Diversifizierung der Bezugsquellen und Investitionen in Recyclingtechnologie reduziert werden kann.","Rohstoffimporte machen Deutschland verwundbar.","Diversifizierung und Recycling können die Rohstoffabhängigkeit verringern.","Kritische Rohstoffe müssen gesichert und recycelt werden."],"correctAnswer":"Die Abhängigkeit von Importen kritischer Rohstoffe stellt eine strategische Verwundbarkeit dar, die durch Diversifizierung der Bezugsquellen und Investitionen in Recyclingtechnologie reduziert werden kann."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dieser Befund stellt eine wichtige Erkenntnis für die weitere Forschung ___.","options":["dar","her","vor","nach"],"correctAnswer":"dar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The high inflation constitutes a considerable risk for the economy","wordBankItems":["Die","hohe","Inflation","stellt","ein","erhebliches","Risiko","für","die","Wirtschaft","dar","."],"correctAnswer":"Die hohe Inflation stellt ein erhebliches Risiko für die Wirtschaft dar ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verwundbarkeit'' means?","options":["vulnerability","weakness","susceptibility","fragility"],"correctAnswer":"vulnerability"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000225',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss agricultural policy at B2","Use Agrarpolitik vocabulary","Talk about CAP and farming"],"explanation":{"intro":"Agricultural policy vocabulary covers EU farm policy, subsidies, and sustainable agriculture at B2.","culturalNote":"EU-Agrarpolitik (Common Agricultural Policy — CAP): largest item in EU budget (~32%). Germany receives ~€5bn/year. Key terms: Direktzahlungen (direct payments), Agrarsubventionen (agricultural subsidies), ökologischer Landbau (organic farming — ~11% of German farmland), Flächenprämien (area-based payments). Key issues: Bauernproteste (farmer protests 2024 against subsidy cuts), Nitratbelastung (nitrate pollution), Insektensterben (insect die-off), Tierwohl (animal welfare), Flächenkonkurrenz (land use competition — biofuel vs. food vs. nature)."},"examples":[{"german":"Die Gemeinsame Agrarpolitik steht vor dem Widerspruch, einerseits Einkommenssicherheit für Landwirte zu gewährleisten und andererseits ökologische Anforderungen durchzusetzen.","english":"The Common Agricultural Policy faces the contradiction of, on the one hand, ensuring income security for farmers and, on the other, enforcing ecological requirements."},{"german":"Eine nachhaltige Landwirtschaft erfordert einen grundlegenden Wandel der Produktionsmethoden, der weit über kosmetische Reformen der Subventionssysteme hinausgehen muss.","english":"Sustainable agriculture requires a fundamental change of production methods that must go far beyond cosmetic reforms of subsidy systems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss agricultural policy, the CAP, and sustainable farming at B2."}}',
'{"items":[{"word":"der Widerspruch","translation":"contradiction","pronunciation":"dayr VI-der-shprookh","example":"Vor einem Widerspruch stehen."},{"word":"durchsetzen","translation":"to enforce/push through","pronunciation":"DOORKH-zetsen","example":"Anforderungen durchsetzen."},{"word":"kosmetisch","translation":"cosmetic","pronunciation":"kos-MEH-tish","example":"Kosmetische Reformen."},{"word":"der Landwirt","translation":"farmer","pronunciation":"dayr LANT-virt","example":"Einkommenssicherheit für Landwirte."},{"word":"der Wandel","translation":"change/transformation","pronunciation":"dayr VAN-del","example":"Grundlegender Wandel."},{"word":"die Einkommenssicherheit","translation":"income security","pronunciation":"dee YN-ko-mens-zi-kher-hyt","example":"Einkommenssicherheit."}]}',
'{"title":"Vor dem Widerspruch stehen — to face the contradiction (formal framing of dilemma)","pattern":"vor dem Widerspruch stehen, X zu tun und Y zu tun = to face the contradiction of doing X and doing Y","explanation":"Vor einem Widerspruch stehen = to face a contradiction (a situation where two legitimate goals conflict). Similar frame: vor einem Dilemma stehen (to face a dilemma), vor der Herausforderung stehen (to face the challenge). This framing is widely used in academic policy analysis to acknowledge legitimate competing interests without dismissing either. Compare: gefangen sein zwischen (to be caught between), im Spannungsfeld stehen zwischen (to stand in the tension between).","examples":[{"sentence":"Die Regierung steht vor dem Widerspruch, Wachstum zu fördern und gleichzeitig den Haushalt zu konsolidieren.","translation":"The government faces the contradiction of promoting growth while at the same time consolidating the budget."},{"sentence":"Eltern stehen oft vor dem Widerspruch, Kinder zu schützen und ihnen Freiheit zu lassen.","translation":"Parents often face the contradiction of protecting children and allowing them freedom."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kosmetisch'' means?","options":["cosmetic","superficial","minor","token"],"correctAnswer":"cosmetic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Common Agricultural Policy faces the contradiction of, on the one hand, ensuring income security for farmers and, on the other, enforcing ecological requirements.","options":["Die Gemeinsame Agrarpolitik steht vor dem Widerspruch, einerseits Einkommenssicherheit für Landwirte zu gewährleisten und andererseits ökologische Anforderungen durchzusetzen.","Die CAP muss Landwirte und Umwelt gleichzeitig schützen.","Agrarpolitik muss zwischen Einkommen und Ökologie abwägen.","Subventionen sichern Einkommen, schaden aber der Umwelt."],"correctAnswer":"Die Gemeinsame Agrarpolitik steht vor dem Widerspruch, einerseits Einkommenssicherheit für Landwirte zu gewährleisten und andererseits ökologische Anforderungen durchzusetzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Regierung steht vor dem Widerspruch, Wachstum zu fördern und gleichzeitig den Haushalt zu ___.","options":["konsolidieren","sanieren","ausgleichen","stabilisieren"],"correctAnswer":"konsolidieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Parents often face the contradiction of protecting children and allowing them freedom","wordBankItems":["Eltern","stehen","oft","vor","dem","Widerspruch",",","Kinder","zu","schützen","und","ihnen","Freiheit","zu","lassen","."],"correctAnswer":"Eltern stehen oft vor dem Widerspruch , Kinder zu schützen und ihnen Freiheit zu lassen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Durchsetzen'' means?","options":["to enforce/push through","to implement","to impose","to assert"],"correctAnswer":"to enforce/push through"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000226',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss food security at B2","Use Ernährungssicherheit vocabulary","Talk about global food systems"],"explanation":{"intro":"Food security vocabulary covers global food supply chains, hunger, and sustainable food systems at B2.","culturalNote":"Ernährungssicherheit (food security): 4 pillars — Verfügbarkeit (availability), Zugang (access), Verwertung (utilisation), Stabilität (stability). ~800 million people globally food insecure. Germany''s role: major food exporter (EU agricultural surplus), but also consumer of globally sourced products. Key issues: Lebensmittelverschwendung (food waste — ~12 million tonnes/year in Germany), Überernährung vs. Unterernährung (over- vs. under-nutrition). UN Sustainable Development Goal 2: Zero Hunger."},"examples":[{"german":"Globale Ernährungssicherheit ist nicht allein ein Produktionsproblem, sondern vor allem ein Problem ungleicher Verteilung, Armut und fehlender politischer Steuerung.","english":"Global food security is not merely a production problem, but above all a problem of unequal distribution, poverty, and absence of political governance."},{"german":"Lebensmittelverschwendung entlang der gesamten Wertschöpfungskette — von der Produktion bis zum Haushalt — konterkariert Bemühungen um nachhaltige Ernährungssysteme.","english":"Food waste along the entire value chain — from production to the household — undermines efforts towards sustainable food systems."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss food security, food waste, and global food systems at B2."}}',
'{"items":[{"word":"die Steuerung","translation":"governance/steering","pronunciation":"dee SHTOY-er-oong","example":"Politische Steuerung."},{"word":"konterkarieren","translation":"to undermine/counteract","pronunciation":"kon-ter-kah-REER-en","example":"Bemühungen konterkarieren."},{"word":"die Wertschöpfungskette","translation":"value chain","pronunciation":"dee VERT-shöp-foonks-ket-eh","example":"Entlang der Wertschöpfungskette."},{"word":"entlang","translation":"along","pronunciation":"ent-LANG","example":"Entlang der Kette."},{"word":"die Verteilung","translation":"distribution","pronunciation":"dee fer-TY-loong","example":"Ungleiche Verteilung."},{"word":"vor allem","translation":"above all/especially","pronunciation":"for AL-em","example":"Vor allem ein Problem."}]}',
'{"title":"Konterkarieren — to undermine, counteract (formal/academic)","pattern":"etwas konterkariert etwas = something undermines/counteracts something (formal — contradicts/neutralises an effort)","explanation":"Konterkarieren = to undermine, counteract, work against (formal/academic — used when one thing neutralises the positive effect of another). Lebensmittelverschwendung konterkariert Bemühungen um Nachhaltigkeit = Food waste undermines efforts towards sustainability. From French contrecarrer. Compare: untergraben (to undermine — also formal, slightly more physical metaphor), zunichtemachen (to nullify/undo — stronger, makes completely void), sabotieren (to sabotage — implies intent), hemmen (to hinder/impede — does not necessarily negate).","examples":[{"sentence":"Sparmaßnahmen konterkarieren die Wachstumsstrategie der Regierung.","translation":"Austerity measures counteract the government''s growth strategy."},{"sentence":"Widersprüchliche Signale konterkarieren das Vertrauen der Investoren.","translation":"Contradictory signals undermine investor confidence."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Steuerung'' means?","options":["governance/steering","control","management","direction"],"correctAnswer":"governance/steering"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Global food security is not merely a production problem, but above all a problem of unequal distribution, poverty, and absence of political governance.","options":["Globale Ernährungssicherheit ist nicht allein ein Produktionsproblem, sondern vor allem ein Problem ungleicher Verteilung, Armut und fehlender politischer Steuerung.","Hunger ist nicht nur ein Produktionsproblem, sondern ein Verteilungsproblem.","Ernährungssicherheit erfordert gerechte Verteilung und politische Lösungen.","Armut und ungleiche Verteilung verursachen Hunger weltweit."],"correctAnswer":"Globale Ernährungssicherheit ist nicht allein ein Produktionsproblem, sondern vor allem ein Problem ungleicher Verteilung, Armut und fehlender politischer Steuerung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sparmaßnahmen konterkarieren die Wachstumsstrategie der ___.","options":["Regierung","Wirtschaft","Regierung","Politik"],"correctAnswer":"Regierung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Contradictory signals undermine investor confidence","wordBankItems":["Widersprüchliche","Signale","konterkarieren","das","Vertrauen","der","Investoren","."],"correctAnswer":"Widersprüchliche Signale konterkarieren das Vertrauen der Investoren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vor allem'' means?","options":["above all/especially","first of all","primarily","most importantly"],"correctAnswer":"above all/especially"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

